export function nationalBuildingFootprint(building: NationalBuilding): NationalPoint[] {
  const c = Math.cos(building.angle), s = Math.sin(building.angle),
    cx = building.x + s * building.footprintOffset, cz = building.z + c * building.footprintOffset;
  return [[-building.width / 2, -building.depth / 2], [building.width / 2, -building.depth / 2],
    [building.width / 2, building.depth / 2], [-building.width / 2, building.depth / 2]]
    .map(([x, z]) => [cx + x * c + z * s, cz - x * s + z * c]);
}
